SELECT inv.invoice_id, c.customer_name, inv.price, COUNT(con.user_id) AS contacts_cnt, COUNT(cust_con.customer_id) AS trusted_contacts_cnt FROM Invoices inv JOIN Customers c ON inv.user_id = c.customer_id LEFT JOIN Contacts con ON inv.user_id = con.user_id LEFT JOIN Customers cust_con ON con.contact_email = cust_con.email GROUP BY inv.invoice_id, c.customer_name, inv.price ORDER BY inv.invoice_id;
